const { existsSync } = await import('node:fs');
if (!process.env.API_KEY) throw new Error('Missing API_KEY');
if (!process.env.INPUT_PATH) throw new Error('Missing INPUT_PATH');
if (!process.env.TARGET) throw new Error('Missing TARGET');
if (!existsSync(process.env.INPUT_PATH)) throw new Error('Input file not found');
globalThis.apiKey = process.env.API_KEY;
globalThis.inputPath = process.env.INPUT_PATH;
globalThis.target = process.env.TARGET;

const { Api2Convert } = await import('@api2convert/sdk');
const path = await import('node:path');
const outDir = path.dirname(globalThis.inputPath);
const ext = '.' + globalThis.target;
const outputPath = path.join(outDir, path.basename(globalThis.inputPath, path.extname(globalThis.inputPath)) + ext);
const client = new Api2Convert(globalThis.apiKey);
const result = await client.convert(globalThis.inputPath, globalThis.target);
await result.save(outputPath);
globalThis.outputPath = outputPath;
